jsonTools.init:
function init(eli) {
  var _esc = function (s) {
    return String(s == null ? "" : s)
      .replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;")
      .replace(/"/g, "&quot;").replace(/'/g, "&#39;");
  };

  // Extract [[...]] placeholders from plain text
  function _extractPlaceholders(text) {
    var found = {};
    var re = /(\$!|\$|!)?\[\[(.+?)\]\]/g;
    var m;
    while ((m = re.exec(text)) !== null) {
      var full = m[0];
      if (full.length > 4) found[full] = true;
    }
    return Object.keys(found);
  }

  // Parse a placeholder into its components
  function _parsePlaceholder(ph) {
    var lookup = null, aiHint = null, guidance = null;
    var raw = ph;
    raw = raw.replace(/\s*\|\s*lookup\s*:\s*([^|\]]+)/gi, function (_, v) { lookup = v.trim(); return ""; });
    raw = raw.replace(/\s*\|\s*(?:ai|ask)\s*:\s*([^|\]]+)/gi, function (_, v) { aiHint = v.trim(); return ""; });
    raw = raw.replace(/\s*\|\s*guidance\s*:\s*([^|\]]+)/gi, function (_, v) { guidance = v.trim(); return ""; });
    // Bare pipe segments (no keyword prefix) → treat as lookup
    raw = raw.replace(/\s*\|\s*([^|\]]+)/gi, function (_, v) {
      var t = v.trim();
      if (t && !lookup) lookup = t;
      return "";
    });
    raw = raw.replace(/[\[\]]/g, "").replace(/^(\$!|\$|!)/, "");
    var prefix = "";
    var prefixMatch = ph.match(/^(\$!|\$|!)?(\[\[)/);
    if (prefixMatch && prefixMatch[1]) prefix = prefixMatch[1];
    var fmt = null;
    raw = raw.replace(/\s*:\s*(UPPER|LOWER|TITLE)\s*(\||$)/gi, function (_, f, tail) { fmt = f.toUpperCase(); return tail; });
    raw = raw.trim();
    var label = "", aiKey = "";
    if (raw.indexOf("||") !== -1) {
      var parts = raw.split("||");
      aiKey = parts[0].trim();
      label = parts[1].trim().replace(/^ask\s*:\s*/i, "");
      // || left side implies lookup (merged concept)
      if (!lookup) lookup = aiKey;
    } else {
      label = raw.replace(/^ask\s*:\s*/i, "");
      aiKey = label;
    }
    // | lookup: sets aiKey too
    if (lookup) aiKey = lookup;
    return { original: ph, prefix: prefix, label: label, aiKey: aiKey, lookup: lookup || "", aiHint: aiHint || "", guidance: guidance || "", fmt: fmt || "" };
  }

  // Rebuild placeholder string from parsed components
  function _buildPlaceholder(p) {
    var inner = p.label;
    if (p.fmt) inner += ":" + p.fmt;
    if (p.lookup) inner += " | lookup:" + p.lookup;
    if (p.aiHint) inner += " | ai:" + p.aiHint;
    if (p.guidance) inner += " | guidance:" + p.guidance;
    return (p.prefix || "") + "[[" + inner + "]]";
  }

  // Extract plain text from OOXML body
  function _ooxmlToText(ooxml) {
    if (!ooxml) return "";
    return String(ooxml).replace(/<w:t[^>]*>([\s\S]*?)<\/w:t>/gi, function (_, t) { return t; })
      .replace(/<[^>]+>/g, "").replace(/&amp;/g, "&").replace(/&lt;/g, "<").replace(/&gt;/g, ">");
  }

  function _show() {
    var mount = document.getElementById("_eli3_dashboard_root");
    if (!mount) return;
    mount.innerHTML = "";
    var root = document.createElement("div");
    root.style.cssText = "position:absolute;top:0;left:0;right:0;bottom:0;z-index:10;background:#f1f5f9;display:flex;flex-direction:column;font-family:Inter,'Segoe UI',system-ui,sans-serif;";

    // Header
    root.innerHTML =
      '<div style="background:linear-gradient(135deg,#0d1b2a,#1b263b);border-bottom:3px solid #c9a227;padding:14px 18px;display:flex;align-items:center;gap:12px;">' +
        '<button class="_pe_back" style="background:none;border:none;color:#cbd5e1;font-size:20px;cursor:pointer;padding:4px 8px;">←</button>' +
        '<div><div style="font:800 9px/1 Inter,sans-serif;letter-spacing:1.4px;color:#d4af37;text-transform:uppercase;">ADMIN</div>' +
        '<div style="font:800 18px/1.15 Georgia,serif;color:#fff;margin-top:3px;">📝 Placeholder Editor</div></div>' +
      '</div>' +
      '<div class="_pe_body" style="flex:1;overflow-y:auto;padding:16px;"></div>';
    root.querySelector("._pe_back").onclick = function () {
      mount.innerHTML = "";
      try { eli.dispatch("tile", "app_placeholder_editor"); } catch (_e) {}
    };
    mount.appendChild(root);
    var body = root.querySelector("._pe_body");

    // Load templates from IDB
    body.innerHTML = '<div style="text-align:center;padding:32px;color:#94a3b8;">Loading templates...</div>';
    eli.storage.getAll("bd_templates").then(function (rows) {
      var templates = (rows || []).filter(function (r) {
        return r && r.id && r.name && r.content && String(r.id).charAt(0) !== "_";
      }).sort(function (a, b) { return String(a.name).localeCompare(String(b.name)); });

      if (!templates.length) {
        body.innerHTML = '<div style="text-align:center;padding:32px;color:#94a3b8;">No templates found in IDB.</div>';
        return;
      }

      body.innerHTML = '';
      // Template picker
      var picker = document.createElement("div");
      picker.style.cssText = "margin-bottom:16px;";
      picker.innerHTML =
        '<label style="font:700 11px/1 Inter,sans-serif;color:#475569;letter-spacing:.05em;display:block;margin-bottom:6px;">SELECT TEMPLATE</label>' +
        '<select class="_pe_sel" style="width:100%;padding:10px 12px;border:2px solid #d4af37;border-radius:10px;font:500 13px/1.3 Inter,sans-serif;color:#0f172a;background:linear-gradient(180deg,#fff,#fafbfc);cursor:pointer;">' +
          '<option value="">— Choose a template —</option>' +
          templates.map(function (t) { return '<option value="' + _esc(t.id) + '">' + _esc(t.name) + '</option>'; }).join("") +
        '</select>';
      body.appendChild(picker);

      var editorArea = document.createElement("div");
      body.appendChild(editorArea);

      picker.querySelector("._pe_sel").onchange = function () {
        var id = this.value;
        if (!id) { editorArea.innerHTML = ""; return; }
        var tpl = templates.filter(function (t) { return t.id === id; })[0];
        if (!tpl) return;
        _renderEditor(tpl, editorArea, templates);
      };
    });
  }

  function _renderEditor(tpl, container, allTemplates) {
    container.innerHTML = '';
    // Parse template content — decompress if pako-compressed (_z: 1)
    var content;
    try {
      var contentStr = tpl.content;
      if (tpl._z === 1 && typeof window.pako !== "undefined" && typeof window.pako.inflate === "function") {
        var utf8 = window.pako.inflate(tpl.content);
        contentStr = new TextDecoder().decode(utf8);
      }
      content = JSON.parse(contentStr);
    } catch (_e) { container.innerHTML = '<div style="color:#b91c1c;">Failed to parse template content: ' + _esc(_e && _e.message || "unknown") + '</div>'; return; }
    var bodyXml = content.body || "";
    var plainText = _ooxmlToText(bodyXml);
    // Also check sections
    var sectionTexts = (content.sections || []).map(function (s) { return _ooxmlToText(s); }).join("\n");
    var allText = plainText + "\n" + sectionTexts;

    var placeholders = _extractPlaceholders(allText);
    if (!placeholders.length) {
      container.innerHTML = '<div style="padding:16px;color:#94a3b8;text-align:center;">No [[...]] placeholders found in this template.</div>';
      return;
    }

    var parsed = placeholders.map(_parsePlaceholder);
    // Scan for over-limit placeholders on load
    var _overLimitOnLoad = placeholders.filter(function (ph) { return ph.length > 255; });
    if (_overLimitOnLoad.length) {
      setTimeout(function () {
        if (typeof showToast === "function") showToast("⚠️ " + _overLimitOnLoad.length + " placeholder(s) exceed 255 chars — these will fail at fill time. Shorten them.", "warn");
      }, 300);
    }
    // All placeholder labels for lookup dropdown
    var allLabels = parsed.map(function (p) { return p.label; });

    // Header
    var hdr = document.createElement("div");
    hdr.style.cssText = "display:flex;align-items:center;justify-content:space-between;margin-bottom:12px;";
    hdr.innerHTML =
      '<div style="font:700 14px/1.2 Inter,sans-serif;color:#0f172a;">' + _esc(tpl.name) + '</div>' +
      '<span style="font:600 10px/1 Inter,sans-serif;color:#94a3b8;background:#f1f5f9;padding:4px 8px;border-radius:6px;">' + placeholders.length + ' placeholders</span>';
    container.appendChild(hdr);

    // Placeholder list
    var list = document.createElement("div");
    list.style.cssText = "display:flex;flex-direction:column;gap:8px;";

    parsed.forEach(function (p, idx) {
      var card = document.createElement("div");
      card.style.cssText = "background:#fff;border:1px solid #e2e8f0;border-left:3px solid #c9a227;border-radius:10px;padding:12px 14px;";

      // Collapsed view — click to expand
      var headerRow = document.createElement("div");
      headerRow.style.cssText = "display:flex;align-items:center;gap:8px;cursor:pointer;";
      headerRow.innerHTML =
        '<span style="font:700 12px/1 Inter,sans-serif;color:#0f172a;flex:1;">' + _esc(p.label) + '</span>' +
        (p.lookup ? '<span style="font:600 9px/1 Inter,sans-serif;color:#0c4a6e;background:#e0f2fe;padding:2px 6px;border-radius:4px;">lookup</span>' : '') +
        (p.aiHint ? '<span style="font:600 9px/1 Inter,sans-serif;color:#92400e;background:#fef3c7;padding:2px 6px;border-radius:4px;">ai</span>' : '') +
        (p.guidance ? '<span style="font:600 9px/1 Inter,sans-serif;color:#166534;background:#f0fdf4;padding:2px 6px;border-radius:4px;">guidance</span>' : '') +
        '<span class="_pe_arrow" style="color:#94a3b8;font-size:12px;">▸</span>';

      var detailPanel = document.createElement("div");
      detailPanel.style.cssText = "display:none;margin-top:10px;padding-top:10px;border-top:1px solid #f1f5f9;";

      var expanded = false;
      headerRow.onclick = function () {
        expanded = !expanded;
        detailPanel.style.display = expanded ? "" : "none";
        headerRow.querySelector("._pe_arrow").textContent = expanded ? "▾" : "▸";
      };

      // Detail fields
      var fieldStyle = 'style="width:100%;padding:6px 10px;border:1px solid #e2e8f0;border-radius:6px;font:400 12px/1.4 Inter,sans-serif;color:#0f172a;box-sizing:border-box;margin-top:3px;"';
      var labelStyle = 'style="font:700 9px/1 Inter,sans-serif;color:#475569;letter-spacing:.08em;text-transform:uppercase;display:block;margin-top:8px;"';

      detailPanel.innerHTML =
        '<label ' + labelStyle + '>Display Label</label>' +
        '<input type="text" class="_pe_label" value="' + _esc(p.label) + '" ' + fieldStyle + '>' +
        '<label ' + labelStyle + '>OARS Lookup Key (field name for OARS matching + {ref} resolution)</label>' +
        '<input type="text" class="_pe_lookup" value="' + _esc(p.lookup) + '" placeholder="Leave empty if same as label" ' + fieldStyle + '>' +
        '<label ' + labelStyle + '>AI Prompt (use {Field Name} for references)</label>' +
        '<textarea class="_pe_ai" rows="2" ' + fieldStyle + '>' + _esc(p.aiHint) + '</textarea>' +
        '<label ' + labelStyle + '>Guidance (shown to user in left column)</label>' +
        '<textarea class="_pe_guidance" rows="2" ' + fieldStyle + '>' + _esc(p.guidance) + '</textarea>' +
        '<label ' + labelStyle + '>Format Suffix</label>' +
        '<select class="_pe_fmt" ' + fieldStyle + '>' +
          '<option value="">— None —</option>' +
          '<option value="UPPER"' + (p.fmt === "UPPER" ? ' selected' : '') + '>UPPER</option>' +
          '<option value="LOWER"' + (p.fmt === "LOWER" ? ' selected' : '') + '>LOWER</option>' +
          '<option value="TITLE"' + (p.fmt === "TITLE" ? ' selected' : '') + '>TITLE</option>' +
        '</select>' +
        '<div class="_pe_preview" style="margin-top:10px;padding:8px 12px;background:#f0f9ff;border:1px solid #bae6fd;border-radius:6px;font:500 11px/1.4 monospace;color:#0c4a6e;word-break:break-all;"></div>';

      // Live preview
      function _updatePreview() {
        var lookupVal = detailPanel.querySelector("._pe_lookup").value.trim();
        var np = {
          prefix: p.prefix,
          label: detailPanel.querySelector("._pe_label").value.trim(),
          aiKey: lookupVal || detailPanel.querySelector("._pe_label").value.trim(),
          lookup: lookupVal,
          aiHint: detailPanel.querySelector("._pe_ai").value.trim(),
          guidance: detailPanel.querySelector("._pe_guidance").value.trim(),
          fmt: detailPanel.querySelector("._pe_fmt").value,
        };
        var built = _buildPlaceholder(np);
        var _previewEl = detailPanel.querySelector("._pe_preview");
        var _charCount = built.length;
        var _overLimit = _charCount > 255;
        _previewEl.innerHTML = _esc(built) +
          '<span style="display:block;margin-top:4px;font:700 10px/1 sans-serif;' +
          (_overLimit ? 'color:#dc2626;">' + _charCount + ' / 255 chars — TOO LONG' : 'color:#64748b;">' + _charCount + ' / 255 chars') +
          '</span>';
        _previewEl.style.borderColor = _overLimit ? "#dc2626" : "#bae6fd";
        _previewEl.style.background = _overLimit ? "#fef2f2" : "#f0f9ff";
        // Store for save
        card._peData = { original: p.original, updated: np };
      }
      // Wire live preview
      setTimeout(function () {
        ["._pe_label", "._pe_lookup", "._pe_ai", "._pe_guidance"].forEach(function (sel) {
          var el = detailPanel.querySelector(sel);
          if (el) el.oninput = _updatePreview;
        });
        ["._pe_fmt"].forEach(function (sel) {
          var el = detailPanel.querySelector(sel);
          if (el) el.onchange = _updatePreview;
        });
        _updatePreview();
      }, 0);

      card.appendChild(headerRow);
      card.appendChild(detailPanel);
      list.appendChild(card);
    });
    container.appendChild(list);

    // Save button
    var saveRow = document.createElement("div");
    saveRow.style.cssText = "margin-top:16px;display:flex;gap:8px;";
    var saveBtn = document.createElement("button");
    saveBtn.type = "button";
    saveBtn.style.cssText = "flex:1;padding:12px 20px;border:none;border-radius:10px;background:linear-gradient(135deg,#c9a227,#dbb846);color:#fff;font:700 13px/1 Inter,sans-serif;cursor:pointer;box-shadow:0 2px 8px rgba(201,162,39,.35);";
    saveBtn.textContent = "💾 Save Changes to Template";
    saveBtn.onclick = function () {
      // Collect all changes
      var changes = [];
      var _tooLong = [];
      list.querySelectorAll("div").forEach(function (card) {
        if (!card._peData) return;
        var d = card._peData;
        var newPh = _buildPlaceholder(d.updated);
        if (newPh.length > 255) {
          _tooLong.push(d.updated.label || newPh.substring(0, 30));
        }
        if (newPh !== d.original) {
          changes.push({ from: d.original, to: newPh });
        }
      });
      if (_tooLong.length) {
        if (typeof showToast === "function") showToast("⚠️ " + _tooLong.length + " placeholder(s) exceed 255 chars: " + _tooLong.join(", ") + ". Shorten before saving.", "err");
        return;
      }
      if (!changes.length) {
        if (typeof showToast === "function") showToast("No changes to save.", "ok");
        return;
      }
      // Apply changes to OOXML body
      var newBody = bodyXml;
      var newSections = (content.sections || []).slice();
      var applied = 0;
      changes.forEach(function (c) {
        // Escape for OOXML text content (reverse the &amp; etc.)
        var fromXml = c.from.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");
        var toXml = c.to.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");
        // Also try unescaped (some templates store raw text)
        if (newBody.indexOf(fromXml) !== -1) {
          newBody = newBody.split(fromXml).join(toXml);
          applied++;
        } else if (newBody.indexOf(c.from) !== -1) {
          newBody = newBody.split(c.from).join(c.to);
          applied++;
        }
        // Also replace in sections (headers/footers)
        newSections = newSections.map(function (s) {
          if (String(s).indexOf(fromXml) !== -1) return s.split(fromXml).join(toXml);
          if (String(s).indexOf(c.from) !== -1) return s.split(c.from).join(c.to);
          return s;
        });
      });
      if (applied === 0) {
        if (typeof showToast === "function") showToast("Could not find placeholders in OOXML (may be split across runs). " + changes.length + " change(s) not applied.", "err");
        return;
      }
      // Save back — re-compress if originally compressed
      content.body = newBody;
      content.sections = newSections;
      var jsonStr = JSON.stringify(content);
      if (tpl._z === 1 && typeof window.pako !== "undefined" && typeof window.pako.deflate === "function") {
        var encoded = new TextEncoder().encode(jsonStr);
        tpl.content = window.pako.deflate(encoded);
        tpl._origLen = jsonStr.length;
      } else {
        tpl.content = jsonStr;
      }
      tpl.modifiedAt = new Date().toISOString();
      eli.storage.put("bd_templates", tpl).then(function () {
        if (typeof showToast === "function") showToast("✅ Saved " + applied + " placeholder change(s) to " + tpl.name, "ok");
        // Re-render to show updated state
        _renderEditor(tpl, container, allTemplates);
      }).catch(function (err) {
        if (typeof showToast === "function") showToast("Save failed: " + (err && err.message), "err");
      });
    };
    saveRow.appendChild(saveBtn);
    container.appendChild(saveRow);
  }

  _show();

  eli.register({
    tile: {
      app_placeholder_editor: function () { _show(); },
    },
  });
}
